// === Tab: midiMagic ===
// OPC SETUP
// You can easily create dynamic variables to use with your midi controller.
// Read full documentation at https://github.com/msawired/OPC
OPC.title('MIDI Controls', 'Enable MIDI above and click on ⋮ to assign controls. Your mappings will be stored in localstorage for this sketch.');
// OPC.title('Circle Settings2', 'Changes various circle attributes');

// Creates a variable "radius" that can be controlled via a slider, with default value 250
// OPC.slider('radius', 500);	//short version. min/max auto-calculated
// OPC.slider('radius', 500, 0, 1000, 10); //min/max/step defined

OPC.slider( //or you can provide an object with full attributes
	{
		name: 'vibrationSpeed',
		value: 0.03,
		min: 0,
		max: 0.5,
		step: 0.001,
		label: 'Speed',
		description: 'Vibration Speed'
	}
);

// overall opacity of the shapes
OPC.slider({
	name: 'opacity',
	value: 1,
	min: 0,
	max: 1,
	step: 0.01,
	label: 'Opacity',
	description: 'Overall opacity'
});

// OPC.toggle('has_stroke', true); //toggle short version
OPC.toggle({ //object version
	name: 'has_stroke',
	value: true,
	label: 'Border',
	description: 'Adds a border'
});

// shape selector. Key is used as label in UI, value is the shape drawn.
OPC.select('shape', {
	"Circle": 'circle',
	"Square": 'square',
	"Quad": 'quad'
});

// Some color palette options to choose from
var myPalettes = [
	["#73C1E8", "#E14747", "#F8E71C", "#73E87A", "#2f004f"],
	["#c3dfe0", "#bcd979", "#9dad6f", "#7d6d61", "#5e574d"],
	["#4464ad", "#a4b0f5", "#f58f29", "#7d4600", "#466995"]
];
OPC.palette('palette', myPalettes);

// for buttons, see ButtonPressed and ButtonReleased functions below
//by default, first argument is used as button label
// OPC.button('pauseButton');	//simple
OPC.button('pauseButton', 'Pause'); //label separate	

// You can also control these via OSC devices through running an OSC server on localhost
// read more here: https://github.com/msawired/OPC#osc-support
// OPC.setOSC('ws://localhost', 8081);

// REST OF THE SKETCH BELOW
var paused = false;
var freakDistanceMax = 120; // wavelength of the opacity ripple
var clock = 0; // animation clock (advances only while playing)
var currentRadius = 50;

// deterministic pseudo-random in 0..1 from two seeds (stable across frames)
function rand2(a, b) {
	let n = Math.sin(a * 127.1 + b * 311.7) * 43758.5453;
	return n - Math.floor(n);
}

// draw an irregular quad whose corner jitter is fixed per grid cell (i, j)
function randomQuad(i, j, x, y, sz) {
	let h = sz / 2;
	let amp = sz * 0.5;
	let jx = (k) => (rand2(i * 3.1 + k * 17.7, j * 2.7 + k * 5.3) - 0.5) * amp;
	let jy = (k) => (rand2(i * 5.7 + k * 11.1, j * 4.3 + k * 9.9) - 0.5) * amp;
	quad(
		x - h + jx(0), y - h + jy(0),
		x + h + jx(1), y - h + jy(1),
		x + h + jx(2), y + h + jy(2),
		x - h + jx(3), y + h + jy(3)
	);
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	rectMode(CENTER); // so square(x, y, sz) is centered on the grid point
}

function draw() {
	window['Frame Rate'] = frameRate().toFixed(0);

	background('#222');

	// advance the animation clock only while playing — pausing freezes the shimmer
	if (!paused) {
		clock += vibrationSpeed;
	}

	// radius drives the grid cell size (and therefore particle density)
	let spacing = map(currentRadius, 0, 1000, 40, 180);
	let baseSize = spacing * 0.62;
	let colorCount = palette.length;

	strokeWeight(map(spacing, 40, 180, 1, 4));
	textAlign(CENTER, CENTER);

	let cols = ceil(width / spacing) + 1;
	let rows = ceil(height / spacing) + 1;

	// center the grid on the canvas
	let offsetX = (width - (cols - 1) * spacing) / 2;
	let offsetY = (height - (rows - 1) * spacing) / 2;

	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			let x = offsetX + i * spacing;
			let y = offsetY + j * spacing;

			// ripple of opacity radiating out from the center = particles "breathing"
			let d = dist(x, y, width / 2, height / 2);
			let raw = (sin(d / freakDistanceMax - clock) + 1) / 2; // 0..1

			let eased = raw;

			let col = color(palette[(i + j) % colorCount]);
			col.setAlpha(eased * 255 * opacity);
			fill(col);

			if (has_stroke) {
				let s = color('#f5f5f5');
				s.setAlpha(eased * 160 * opacity);
				stroke(s);
			} else {
				noStroke();
			}

			let sz = baseSize * (0.2 + 0.9 * eased);

			if (shape === 'square') {
				square(x, y, sz);
			} else if (shape === 'quad') {
				randomQuad(i, j, x, y, sz);
			} else {
				circle(x, y, sz);
			}
		}
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

//parameterChanged function is used every time a parameter is updated.
function parameterChanged(variableName, newValue) {
	// print(variableName,newValue);
}

//BUTTON FUNCTIONS
//buttonPressed function is used every time a button is pressed.
function buttonReleased(variableName) {
	//you can check variableName if you have multiple buttons
	switch (variableName) {
		case 'pauseButton':
			paused = !paused;
			pauseButton = paused ? 'Resume' : 'Pause';
			break;
		case 'Reset':
			radius = 0;
			break;
	}
}

function keyPressed() {
	//you can remotely collapse/expand the configurator sa well
	switch (key) {
		case 'c':
			OPC.collapse();
			break;
		case "e":
			OPC.expand();
			break;
	}
}

